-- Read only. Run before 0015 as well as immediately before 0016.
with related_ids as (select id from public.orders union all select id from public.order_items union all select id from public.order_photos union all select id from public.visits union all select id from public.payments union all select id from public.payment_intents union all select id from public.intake_acts union all select id from public.complaints union all select id from public.rewash_jobs union all select id from public.compensations union all select id from public.order_discounts union all select id from public.pay_accruals union all select id from public.pickup_events union all select id from public.item_measurements union all select id from public.production_events)
select jsonb_build_object('counts',jsonb_build_object('visit_events',(select count(*) from public.visit_events),'visits',(select count(*) from public.visits),'order_defects',(select count(*) from public.order_defects),'item_measurements',(select count(*) from public.item_measurements),'order_photos',(select count(*) from public.order_photos),'pickup_events',(select count(*) from public.pickup_events),'status_history',(select count(*) from public.status_history),'production_events',(select count(*) from public.production_events),'payments',(select count(*) from public.payments),'payment_intents',(select count(*) from public.payment_intents),'intake_acts',(select count(*) from public.intake_acts),'rewash_jobs',(select count(*) from public.rewash_jobs),'compensations',(select count(*) from public.compensations),'complaints',(select count(*) from public.complaints),'feedback',(select count(*) from public.feedback),'order_discounts',(select count(*) from public.order_discounts),'pay_accruals',(select count(*) from public.pay_accruals),'order_creation_keys',(select count(*) from public.order_creation_keys),'order_items',(select count(*) from public.order_items),'orders',(select count(*) from public.orders),'cash_closings',(select count(*) from public.cash_closings),'system_jobs',(select count(*) from public.system_jobs),'tasks',(select count(*) from public.tasks where order_id is not null),'leads',(select count(*) from public.leads where order_id is not null),'integration_outbox',(select count(*) from public.integration_outbox where order_id is not null),'stock_movements',(select count(*) from public.stock_movements where order_id is not null),'calls_detached',(select count(*) from public.calls where order_id is not null),'command_receipts',(select count(*) from public.command_receipts r where exists(select 1 from related_ids i where position(i.id::text in (r.payload::text||r.result::text))>0))),'storage_manifest',(select coalesce(jsonb_agg(jsonb_build_object('path',storage_path)),'[]') from public.order_photos),'retired_staff',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'full_name',full_name,'role',role,'active',active)),'[]') from public.profiles where role::text not in ('operator','driver','warehouse','washer','packer','admin')),'audit_preserved',(select count(*) from public.audit_log));
